import {createAssemblyStore,assemblyStorageKey,calculateBuildable,kitReferenceStatus} from './assemblies.mjs';
import {createComponentStore,storageKey} from './data.mjs';
const $=s=>document.querySelector(s),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
let editing=null,rows=[],kitDraft=null;
const form=$('#assembly-form'),field=k=>form.elements.namedItem(k),store=()=>createAssemblyStore(window.localStorage),components=()=>createComponentStore(window.localStorage).list();
const kitRoles={potentiometers:{label:'Potentiometers',category:'potentiometers'},neckCapacitor:{label:'Neck tone capacitor',category:'capacitors'},bridgeCapacitor:{label:'Bridge tone capacitor',category:'capacitors'},trebleBleed:{label:'Treble bleed',category:'treble-bleeds'},jack:{label:'Output jack',category:'jacks'},selector:{label:'Selector switch',category:'switches'}};
function error(e){$('#assembly-error').textContent=e.message;}
function refresh(){document.dispatchEvent(new Event('assemblies-changed'));}
export function renderAssemblies(query=''){
 const inventory=components(),list=store().list().filter(a=>[a.name,a.sku,a.category,a.kitDefinition?.family].join(' ').toLowerCase().includes(query));$('#count').textContent=list.length+' assemblies';$('#table-caption').textContent='Products / Assemblies';const header=el('tr');for(const title of ['Assembly','Type','Category','BOM rows','Max buildable','Active','Edit'])header.append(el('th',title));$('#table-head').replaceChildren(header);$('#table-body').replaceChildren();$('#empty').hidden=!!list.length;$('#empty').textContent='No assemblies yet, or none match your search. Add an assembly and configure its BOM manually.';
 for(const a of list){const tr=el('tr'),name=el('td',a.name);name.append(el('small',a.sku));tr.append(name,el('td',a.kind==='wiring-kit'?'Wiring Kit Definition':'Assembly'),el('td',a.category),el('td',String(a.bom.length)));const availability=el('td');showBuildable(availability,a.bom,inventory);tr.append(availability,el('td',a.active?'Active':'Inactive'));const actions=el('td');for(const [label,action] of [['Edit',()=>open(a.id)],['Delete',()=>{if(window.confirm('Delete assembly “'+a.name+'”? Component inventory will not be changed.')){store().remove(a.id);refresh();$('#status').textContent='Assembly deleted. Component stock unchanged.';}}]]){const button=el('button',label);button.type='button';if(label==='Delete')button.className='destructive';button.setAttribute('aria-label',label+' '+a.name);button.addEventListener('click',()=>{try{action();}catch(e){$('#status').textContent=e.message;}});actions.append(button);}tr.append(actions);$('#table-body').append(tr);}
}
function open(id=null){editing=id;const a=id?store().list().find(a=>a.id===id):{name:'',sku:'',category:'Other',kind:'assembly',active:true,bom:[]};if(!a)throw new Error('Assembly no longer exists.');form.reset();for(const key of ['name','sku','category'])field(key).value=a[key];field('kind').value=a.kind==='wiring-kit'?'wiring-kit':'assembly';field('active').checked=a.active;rows=structuredClone(a.bom);kitDraft=a.kind==='wiring-kit'?structuredClone(a.kitDefinition):{family:'',showOnWiringKits:false,builderEnabled:false,permittedComponentIds:[],defaults:{wiring:'50s',componentIds:Object.fromEntries(Object.keys(kitRoles).map(role=>[role,null]))},metadata:{wiringOptions:['50s','60s','modern'],matchingOptions:['standard','precision']}};$('#assembly-title').textContent=id?'Edit assembly':'Add assembly';$('#assembly-error').textContent='';renderKitFields();renderRows();$('#assembly-dialog').showModal();}
function renderKitFields(){
 const isKit=field('kind').value==='wiring-kit',root=$('#kit-definition-fields');root.hidden=!isKit;if(!isKit)return;
 field('kitFamily').value=kitDraft.family||'';field('defaultWiring').value=kitDraft.defaults?.wiring||'50s';field('showOnWiringKits').checked=!!kitDraft.showOnWiringKits;field('builderEnabled').checked=!!kitDraft.builderEnabled;
 const inventory=components(),choices=$('#kit-permitted-components');choices.replaceChildren();for(const component of inventory.filter(p=>p.inKits||kitDraft.permittedComponentIds.includes(p.id))){const label=el('label'),input=el('input');input.type='checkbox';input.checked=kitDraft.permittedComponentIds.includes(component.id);input.addEventListener('change',()=>{if(input.checked)kitDraft.permittedComponentIds.push(component.id);else{kitDraft.permittedComponentIds=kitDraft.permittedComponentIds.filter(id=>id!==component.id);for(const role of Object.keys(kitRoles))if(kitDraft.defaults.componentIds[role]===component.id)kitDraft.defaults.componentIds[role]=null;}renderKitDefaults();});label.append(input,document.createTextNode(' '+component.name+' · '+component.id+(component.active&&component.inKits?'':' · CURRENTLY INELIGIBLE')));choices.append(label);}
 if(!choices.children.length)choices.append(el('p','No Components are currently marked Available in wiring kits.'));
 renderKitDefaults();const status=kitReferenceStatus({kind:'wiring-kit',kitDefinition:kitDraft},inventory);$('#kit-reference-status').textContent=status.warnings.length?status.warnings.join(' '):'All referenced Component IDs exist.';
}
function renderKitDefaults(){const inventory=components(),root=$('#kit-default-components');root.replaceChildren();for(const [role,settings] of Object.entries(kitRoles)){const label=el('label',settings.label),select=el('select'),none=el('option','None');none.value='';select.append(none);const selected=kitDraft.defaults.componentIds[role];if(selected&&!inventory.some(p=>p.id===selected)){const missing=el('option','Missing Component: '+selected);missing.value=selected;select.append(missing);}for(const component of inventory.filter(p=>p.category===settings.category&&kitDraft.permittedComponentIds.includes(p.id))){const option=el('option',component.name+' · '+component.id);option.value=component.id;select.append(option);}select.value=selected||'';select.addEventListener('change',()=>{kitDraft.defaults.componentIds[role]=select.value||null;});label.append(select);root.append(label);}}
function renderRows(focus=false){const inventory=components(),root=$('#assembly-bom');root.replaceChildren();rows.forEach((row,index)=>{const group=el('div');group.className='assembly-bom-row';const label=el('label','Component'),select=el('select');select.required=true;select.setAttribute('aria-label','BOM component '+(index+1));const blank=el('option','Choose component');blank.value='';select.append(blank);if(row.componentId&&!inventory.some(p=>p.id===row.componentId)){const missing=el('option','Missing component: '+row.componentId);missing.value=row.componentId;select.append(missing);}for(const p of inventory){const option=el('option',p.name+' · '+p.sku+(p.active?'':' · INACTIVE'));option.value=p.id;select.append(option);}select.value=row.componentId;select.addEventListener('change',()=>{row.componentId=select.value;updatePreview();});label.append(select);const qtyLabel=el('label','Quantity required'),input=el('input');input.type='number';input.min='1';input.step='1';input.required=true;input.value=row.quantity;input.setAttribute('aria-label','BOM quantity '+(index+1));input.addEventListener('input',()=>{row.quantity=input.value;updatePreview();});qtyLabel.append(input);const remove=el('button','Remove');remove.type='button';remove.setAttribute('aria-label','Remove BOM row '+(index+1));remove.addEventListener('click',()=>{rows.splice(index,1);renderRows();(root.children[Math.min(index,rows.length-1)]?.querySelector('select')||$('#add-bom-row')).focus();});group.append(label,qtyLabel,remove);root.append(group);});if(!rows.length)root.append(el('p','No BOM components. Add the parts required to build one assembly.'));updatePreview();if(focus)root.lastElementChild?.querySelector('select')?.focus();}
$('#add-assembly').addEventListener('click',()=>{try{open();}catch(e){$('#status').textContent=e.message;}});
$('#add-bom-row').addEventListener('click',()=>{rows.push({componentId:'',quantity:1});try{renderRows(true);}catch(e){error(e);}});
field('kind').addEventListener('change',renderKitFields);
form.addEventListener('submit',e=>{e.preventDefault();try{const kind=field('kind').value;if(kind==='wiring-kit')kitDraft={...kitDraft,family:field('kitFamily').value,showOnWiringKits:field('showOnWiringKits').checked,builderEnabled:field('builderEnabled').checked,defaults:{...kitDraft.defaults,wiring:field('defaultWiring').value}};store().save({name:field('name').value,sku:field('sku').value,category:field('category').value,kind,active:field('active').checked,bom:rows,kitDefinition:kind==='wiring-kit'?kitDraft:undefined},editing);$('#assembly-dialog').close();refresh();$('#status').textContent='Assembly saved in this browser. No stock consumed.';}catch(e){error(e);}});
window.addEventListener('storage',e=>{if(e.key===assemblyStorageKey||e.key===storageKey||e.key===null){refresh();if($('#assembly-dialog').open)updatePreview();}});

function showBuildable(target,bom,inventory){
 const result=calculateBuildable(bom,inventory);target.replaceChildren(el('strong',result.quantity===null?'Not calculated':String(result.quantity)));
 if(result.warnings.length){for(const warning of result.warnings)target.append(el('p',warning));target.classList.add('assembly-warning');}else{target.classList.remove('assembly-warning');if(result.limiting.length)target.append(el('small','Limited by: '+result.limiting.map(p=>p.name+' ('+p.stock+' available / '+p.requiredQuantity+' required)').join('; ')));else target.append(el('small','Add a BOM to calculate availability.'));}
}
function updatePreview(){try{showBuildable($('#assembly-buildable'),rows,components());}catch(e){$('#assembly-buildable').textContent='Not calculated. '+e.message;}}
